#include <stdio.h>

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    long long sums[1000] = {0};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int value;
            scanf("%d", &value);
            sums[j] += value;
        }
    }

    long long answer = sums[0];
    for (int j = 1; j < M; j++) {
        if (sums[j] < answer) answer = sums[j];
    }

    printf("%lld\n", answer);
    return 0;
}
